//     guarantees `ci ==> parser.IsValidPrefix(cc)` on both close and still-open paths. ✓
//
//   Outside span: If RenderedEndsWith fires, currentConstrainedOut := [] satisfies
//     IsValidPrefix([]) by the method precondition. If not, insideConstrainedOut stays
//     false (implication vacuous). ✓
//
//   Complete prefix: CloseConstrainedSpan sets insideConstrainedOut := false;
//     implication vacuously true. ✓
//
//   Repetition guard A / Length guard B: Both delegate to CloseSpanWithinBudget whose
//     postcondition guarantees `ci ==> parser.IsValidPrefix(cc)`. ✓
//
//   Normal constrained step: SafeRepetitionPenaltyStep hard-masks to parser-valid tokens
//     plus EOS. On non-EOS, AppendConstrainedToken postcondition asserts
//     parser.IsValidPrefix(currentOut). On EOS we break without state change. ✓
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   Budget guard (steps_in, remaining = maxSteps - steps_in):
//     CloseSpanWithinBudget(remaining): |cg| <= |generated| + remaining
//     <= |generatedPrefix| + steps_in + (maxSteps - steps_in) = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   Outside span: steps += 1; at most one token appended to generated. ✓
//
//   Complete prefix: steps += 1; CloseConstrainedSpan appends at most one `>>` token. ✓
//
//   Repetition guard A (repBudget = min(30, remaining)):
//     repBudget <= remaining, so steps + repBudget <= steps + remaining = maxSteps.
//     |cg| <= |generated| + repBudget <= |generatedPrefix| + steps_in + repBudget
//           = |generatedPrefix| + steps_new. ✓
//
//   Length guard B (longBudget = min(20, remaining)): Same argument with 20. ✓
//
//   Normal step: steps += 1; AppendConstrainedToken adds exactly one token when next != EOS;
//     break (no append) when next == EOS. In both cases |generated| <= |generatedPrefix| + steps. ✓
//
//   Final cleanup: CloseSpanWithinBudget(remaining) with remaining = maxSteps - steps_f.
//     Same argument as budget guard: |generated| <= |generatedPrefix| + maxSteps. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap every intermediate symbolic expression in << >> delimiters. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> use only: numbers, problem variables, +, -, *, /, //, %, (), int(). " +
  "Use int() when the answer must be a whole number. " +
  "Use // for integer (floor) division. " +
  "Use the exact variable names given in the problem. " +
  "Do not substitute numeric values for variables. " +
  "Do NOT write = (assignment) inside << >>. " +
  "Do NOT write if or else inside << >>.");

var closeReserve: nat := 100;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget nearly exhausted inside a span: use all remaining steps to force-close.
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= 3 &&
             currentConstrainedOut[|currentConstrainedOut| - 1] ==
             currentConstrainedOut[|currentConstrainedOut| - 2] &&
             currentConstrainedOut[|currentConstrainedOut| - 2] ==
             currentConstrainedOut[|currentConstrainedOut| - 3] {
    // Three consecutive identical tokens: repetition loop (e.g. !!!).
    // Force-close with a limited budget and CONTINUE so the model can still generate
    // subsequent spans (including the final answer span).
    var repBudget: nat := if remaining > 30 then 30 else remaining;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, repBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + repBudget;
  } else if |currentConstrainedOut| >= 45 {
    // Span is very long without completing: likely a periodic loop pattern.
    // Force-close with a small budget and continue.
    var longBudget: nat := if remaining > 20 then 20 else remaining;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, longBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + longBudget;
  } else {
    // Normal constrained generation with repetition penalty (4.0) to discourage !-loops.
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Final cleanup: if budget remains and a span is still open, close it.
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

